import lote08_base as B
L = []
HAR = "Harrison Principios de Medicina Interna 21.ª ed. (2022)"
NEL = "Nelson Tratado de Pediatría 22.ª ed. (2024)"
WIL = "Williams Obstetricia 26.ª ed. (2022)"
